@extends('layouts.app')@section('title',ucfirst($mode))@section('content')<main class="auth-page"><span class="eyebrow muted">WELCOME TO {{ strtoupper($store['name']??'NOVACART') }}</span><h1>{{ ['login'=>'Good to see you.','register'=>'Make yourself at home.','forgot'=>'Reset your password.','reset'=>'Choose a new password.'][$mode] }}</h1><form class="panel-form" method="post" action="{{ ['login'=>'/login','register'=>'/register','forgot'=>'/password/email','reset'=>'/password/reset'][$mode] }}">@csrf @if($mode==='reset')<input type="hidden" name="token" value="{{ $token }}">@endif @if($mode==='register')<label>Name<input name="name" required autocomplete="name" value="{{ old('name') }}"></label>@endif<label>Email<input type="email" name="email" required autocomplete="email" value="{{ old('email',$email??'') }}"></label>@if(in_array($mode,['login','register','reset']))<label>Password<input name="password" type="password" minlength="8" required autocomplete="{{ $mode==='login'?'current-password':'new-password' }}"></label>@endif @if(in_array($mode,['register','reset']))<label>Confirm password<input name="password_confirmation" type="password" minlength="8" required autocomplete="new-password"></label>@endif @if($mode==='login')<label class="check-label"><input type="checkbox" name="remember" value="1"> Remember me</label>@endif<button class="primary full">{{ ['login'=>'Sign in','register'=>'Create account','forgot'=>'Send reset link','reset'=>'Reset password'][$mode] }}</button></form><div class="auth-links">@if($mode==='login')<a href="/password/reset">Forgot password?</a><a href="/register">Create an account</a>@else<a href="/login">Back to sign in</a>@endif</div>@if(in_array($mode,['register','forgot']))<p class="small muted">Demo email uses the log mail driver. Verification and reset links are written to the local Laravel log until SMTP is configured.</p>@endif</main>@endsection
